package com.company.logicdelete.analyzer;
import com.company.logicdelete.common.*;import org.junit.jupiter.api.Test;import java.nio.file.Paths;import static org.junit.jupiter.api.Assertions.*;
class SqlAnalyzerTest {private LogicDeleteConfig config(){LogicDeleteConfig c=new LogicDeleteConfig();LogicDeleteConfig.ControlledTable t=new LogicDeleteConfig.ControlledTable();t.setSchema("public");t.setTable("order_main");t.setDeleteField("delete_flag");c.getTables().add(t);return c;}private AnalysisModels.Result analyze(String tag,String sql){AnalysisModels.Statement s=new AnalysisModels.Statement();s.namespace="x.Mapper";s.id="test";s.tag=tag;s.sql=sql;s.file=Paths.get("mapper.xml");return new SqlAnalyzer().analyze(s,config());}@Test void ignoresCommentsAndLiterals(){AnalysisModels.Result r=analyze("select","select 'order_main' -- from order_main\n from other");assertTrue(r.controlled.isEmpty());}@Test void findsPhysicalDelete(){AnalysisModels.Result r=analyze("delete","delete from PUBLIC.\"order_main\" where id=#{id}");assertTrue(r.physicalDelete);assertTrue(r.codes().contains("PHYSICAL_DELETE"));}@Test void findsFlag(){assertTrue(analyze("select","select * from order_main where o.DELETE_FLAG=0").deleteFlag);}}
